mapper.select:
SELECT id::text AS id, user_id, username, ip_address::text AS ip_address, login_location, browser, os, status, msg, login_time FROM sys_login_log
AND username LIKE CONCAT('%', #{username}, '%')
AND status = #{status}
AND login_time >= CAST(#{beginTime} AS timestamp)
AND login_time <= CAST(#{endTime} AS timestamp)
ORDER BY login_time DESC LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM sys_login_log
WHERE id = #{id}
  AND login_time = #{loginTime}
